import { ApplicationConfig, provideBrowserGlobalErrorListeners } from '@angular/core';
import { provideHttpClient, withInterceptors } from '@angular/common/http';
import { provideRouter } from '@angular/router';
import { routes } from './app.routes';
import { userHeader } from './core/session';

// The app's wiring: the router and the HTTP client (which sends the signed-in user's name).
export const appConfig: ApplicationConfig = {
  providers: [
    provideBrowserGlobalErrorListeners(),
    provideRouter(routes),
    provideHttpClient(withInterceptors([userHeader])),
  ],
};
import { HttpClient, HttpInterceptorFn } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { Observable, tap } from 'rxjs';

// Who is signed in. There is no password: a name is typed, the server checks it and echoes it back.
@Injectable({ providedIn: 'root' })
export class Session {
  private readonly http = inject(HttpClient);
  private readonly name = signal<string | null>(null);
  readonly user = this.name.asReadonly();

  signIn(name: string): Observable<{ name: string }> {
    return this.http
      .post<{ name: string }>('/api/session', { name })
      .pipe(tap((u) => this.name.set(u.name)));
  }
}

// Every API call carries the signed-in name in the X-User header.
export const userHeader: HttpInterceptorFn = (req, next) => {
  const user = inject(Session).user();
  return next(user ? req.clone({ setHeaders: { 'X-User': user } }) : req);
};
package net.officefloor.hq.app.sheet;

import org.springframework.context.annotation.Configuration;
import org.springframework.web.servlet.config.annotation.InterceptorRegistry;
import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;

/** Puts the {@link ArchiveGuard} in front of a sheet's API, except loading it and its bulk actions. */
@Configuration
public class ArchiveGuardConfig implements WebMvcConfigurer {

    private final ArchiveGuard guard;

    public ArchiveGuardConfig(ArchiveGuard guard) {
        this.guard = guard;
    }

    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        registry.addInterceptor(guard)
                .addPathPatterns("/api/sheets/**")
                .excludePathPatterns("/api/sheets/*/load", "/api/sheets/*/claims/bulk-*");
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.util.Map;
import org.springframework.http.HttpMethod;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.web.servlet.HandlerInterceptor;
import org.springframework.web.servlet.HandlerMapping;

/**
 * Refuses every change asked for on an archived sheet: any request on it other than a read is refused before it
 * reaches its handler, so it writes nothing. Loading the sheet and the bulk actions (taken with every selected item
 * refused) are left to their handlers; see {@link ArchiveGuardConfig}.
 */
@Component
public class ArchiveGuard implements HandlerInterceptor {

    private final SheetService sheets;

    public ArchiveGuard(SheetService sheets) {
        this.sheets = sheets;
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        String method = request.getMethod();
        if (HttpMethod.GET.matches(method) || HttpMethod.HEAD.matches(method) || HttpMethod.OPTIONS.matches(method)) {
            return true;
        }
        String sheetId = sheetId(request);
        if (sheetId != null && sheets.isArchived(sheetId)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The sheet is archived: nothing on it can change");
        }
        return true;
    }

    @SuppressWarnings("unchecked")
    private static String sheetId(HttpServletRequest request) {
        Object vars = request.getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
        if (!(vars instanceof Map<?, ?> map)) {
            return null;
        }
        Map<String, String> path = (Map<String, String>) map;
        return path.containsKey("sheetId") ? path.get("sheetId") : path.get("id");
    }
}
package net.officefloor.hq.app.role;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.util.Map;
import org.springframework.http.HttpMethod;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.web.servlet.HandlerInterceptor;
import org.springframework.web.servlet.HandlerMapping;

/**
 * Refuses every change a viewer asks for on a sheet: any request on a sheet other than a read is refused before
 * it reaches its handler, so it writes nothing. Loading the sheet and the bulk actions (which a viewer takes with
 * every selected item refused) are left to their handlers; see {@link ViewerGuardConfig}.
 */
@Component
public class ViewerGuard implements HandlerInterceptor {

    private final RoleService roles;

    public ViewerGuard(RoleService roles) {
        this.roles = roles;
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        String method = request.getMethod();
        if (HttpMethod.GET.matches(method) || HttpMethod.HEAD.matches(method) || HttpMethod.OPTIONS.matches(method)) {
            return true;
        }
        String user = request.getHeader("X-User");
        String sheetId = sheetId(request);
        if (user == null || sheetId == null) {
            return true;
        }
        if (roles.isViewer(sheetId, user.trim())) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "A viewer cannot change anything on this sheet");
        }
        return true;
    }

    @SuppressWarnings("unchecked")
    private static String sheetId(HttpServletRequest request) {
        Object vars = request.getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
        if (!(vars instanceof Map<?, ?> map)) {
            return null;
        }
        Map<String, String> path = (Map<String, String>) map;
        return path.containsKey("sheetId") ? path.get("sheetId") : path.get("id");
    }
}
